INSERT INTO v3.metric_definition VALUES('E1','E','Required Learning Completion',4500,'%','identity','Completed / assigned learning items.') ON CONFLICT DO NOTHING;
INSERT INTO v3.metric_definition VALUES('E2','E','Training Start Rate',1000,'%','identity','Distinct started / assigned learners.') ON CONFLICT DO NOTHING;
INSERT INTO v3.metric_definition VALUES('E3','E','On-Time Training Completion',2000,'%','identity','On-time completed / due assignments.') ON CONFLICT DO NOTHING;
INSERT INTO v3.metric_definition VALUES('E4','E','AI Skill Assessment Completion',2500,'%','identity','Completed / assigned learner-assessment pairs; completion is not passing.') ON CONFLICT DO NOTHING;
INSERT INTO v3.metric_definition VALUES('E5','E','AI Skill Level Gain',0,'ordinal gain','diagnostic','Requires comparable measured pre/post results. No result is inferred from a checkbox.') ON CONFLICT DO NOTHING;
INSERT INTO v3.metric_definition VALUES('A1','A','Copilot Seat Activation Rate',500,'%','identity','Assigned seats with activity / assigned seats.') ON CONFLICT DO NOTHING;
INSERT INTO v3.metric_definition VALUES('A2','A','28-Day AI-Active Rate',2500,'%','identity','AI-active / eligible licensed users in the 28-day window.') ON CONFLICT DO NOTHING;
INSERT INTO v3.metric_definition VALUES('A3','A','Regular Copilot Use Score',2000,'score','source','100 × min(active days, 8) / 8; eight-day target is sample policy only.') ON CONFLICT DO NOTHING;
INSERT INTO v3.metric_definition VALUES('A4','A','Sustained Weekly Copilot Use Rate',3500,'%','identity','User-weeks with at least two active days / eligible user-weeks.') ON CONFLICT DO NOTHING;
INSERT INTO v3.metric_definition VALUES('A5','A','Copilot Agent Adoption Rate',1500,'%','identity','IDE-agent users / AI-active users.') ON CONFLICT DO NOTHING;
INSERT INTO v3.metric_definition VALUES('T1','T','Merged PR Throughput',0,'PRs','diagnostic','Distinct PRs merged to configured mainline.') ON CONFLICT DO NOTHING;
INSERT INTO v3.metric_definition VALUES('T2','T','Median Merged PRs per Active Week',4000,'PRs/week','higher','Median merges per commit-active user-week, including zero-merge active weeks. Sample reference: 4.') ON CONFLICT DO NOTHING;
INSERT INTO v3.metric_definition VALUES('T3','T','Median PR Life-Cycle Time',3000,'hours','lower','PR-open to merge elapsed hours. Sample reference: 24 hours.') ON CONFLICT DO NOTHING;
INSERT INTO v3.metric_definition VALUES('T4','T','Median Time to First Human Review',1000,'hours','lower','PR-open to first human review. Sample reference: 6 hours.') ON CONFLICT DO NOTHING;
INSERT INTO v3.metric_definition VALUES('T5','T','Orphaned PR Rate',2000,'%','inverse','Open non-draft PRs stale more than 30 days / open non-drafts.') ON CONFLICT DO NOTHING;
INSERT INTO v3.metric_definition VALUES('F1','F','Median Development Preparation Time',2500,'hours','lower','Earliest linked commit to PR-open elapsed time, not active labor. Sample reference: 9 hours.') ON CONFLICT DO NOTHING;
INSERT INTO v3.metric_definition VALUES('F2','F','Median Review Cycles',3000,'cycles','lower','Governed cycles per reviewed closed/merged PR. Sample reference: 1.5 cycles.') ON CONFLICT DO NOTHING;
INSERT INTO v3.metric_definition VALUES('F3','F','Median Author Rework Time',2500,'hours','lower','Change-request to author-response time. Sample reference: 4.5 hours.') ON CONFLICT DO NOTHING;
INSERT INTO v3.metric_definition VALUES('F4','F','Copilot Code Acceptance Rate',2000,'%','identity','Acceptance / compatible generation activity counts; anomalies are not capped.') ON CONFLICT DO NOTHING;
INSERT INTO v3.metric_definition VALUES('F5','F','AI Credits per AI-Active User',0,'credits','diagnostic','Scoped credits / AI-active users; own total in self view.') ON CONFLICT DO NOTHING;
INSERT INTO v3.metric_definition VALUES('Q1','Q','CI First-Pass Score',2500,'%','identity','First submission, complete nonempty required checks, attempt 1, initial head >5 changed lines.') ON CONFLICT DO NOTHING;
INSERT INTO v3.metric_definition VALUES('Q2','Q','Revert-Free Score',2000,'%','identity','Unreverted / mature delivered authored commits; 30-day maturity.') ON CONFLICT DO NOTHING;
INSERT INTO v3.metric_definition VALUES('Q3','Q','Review Rework-Free Score',1500,'%','identity','Eligible reviewed merged PRs without valid non-dismissed human change requests.') ON CONFLICT DO NOTHING;
INSERT INTO v3.metric_definition VALUES('Q4','Q','PR Life-Cycle Speed Score',2500,'score','source','100 × approved same-scope baseline / current lifecycle median, capped at 100.') ON CONFLICT DO NOTHING;
INSERT INTO v3.metric_definition VALUES('Q5','Q','Mainline Completion Score',1500,'%','identity','Mature eligible non-reverted commits delivered within seven days.') ON CONFLICT DO NOTHING;
