BEGIN;
SELECT c.id,c.id,1,c.title,CASE WHEN provider='SW Internal' THEN 'internal' WHEN provider IN ('Pluralsight','Microsoft ESI') THEN 'licensed' ELSE 'public' END,
provider NOT IN ('SW Internal','Pluralsight','Microsoft ESI'),'2027-09-01' FROM courses c ON CONFLICT DO NOTHING;
-- Public-access flags are synthetic fixture review evidence, not live link-validation claims.
SELECT gen_random_uuid(),u.id,c.id,c.course_id<>'d4000000-0000-4000-8000-000000000007','2026-09-01','2026-09-30' FROM users u CROSS JOIN v3.course_version c
WHERE u.active AND (u.employment_type='employee' OR c.access_tier='public') ON CONFLICT(user_id,course_version_id) DO NOTHING;
-- Preserve legacy completions in their original table. They are not transformed into attestations.
SELECT gen_random_uuid(),a.user_id,a.course_version_id,a.id,1,CASE WHEN COALESCE(p.percentage,0)>0 THEN 'in_progress' ELSE 'enrolled' END,
LEAST(COALESCE(p.percentage,0),99),CASE WHEN COALESCE(p.percentage,0)>0 THEN now() ELSE NULL END
FROM v3.assignment a LEFT JOIN course_progress p ON p.user_id=a.user_id AND p.course_id=a.course_version_id
ON CONFLICT(user_id,course_version_id,attempt_number) DO NOTHING;

COMMIT;
